alter table public.habits add column if not exists visibility public.visibility_scope not null default 'private', add column if not exists specific_days jsonb;
alter table public.habit_entries add column if not exists status text not null default 'completed' check(status in ('completed','missed','skipped','skipped_planned'));
alter table public.health_entries add column if not exists visibility public.visibility_scope not null default 'private'; alter table public.family_entries add column if not exists visibility public.visibility_scope not null default 'private';
create table public.discipline_settings(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references public.profiles(id),tasks_weight numeric not null default 30,habits_weight numeric not null default 25,workouts_weight numeric not null default 15,planning_weight numeric not null default 10,family_weight numeric not null default 10,financial_weight numeric not null default 10,unique(workspace_id,user_id));
create table public.discipline_scores(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references public.profiles(id),date date not null,total_score numeric not null,calculation_details jsonb not null default '{}'::jsonb,unique(workspace_id,user_id,date)); create table public.special_dates(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references public.profiles(id),title text not null,date date not null,annual boolean not null default true,emoji text not null default '🎂');
alter table public.discipline_settings enable row level security;alter table public.discipline_scores enable row level security;alter table public.special_dates enable row level security;grant select,insert,update,delete on public.discipline_settings,public.discipline_scores,public.special_dates to authenticated;
do $$ declare t text; begin foreach t in array array['habits','habit_entries','health_entries','workouts','family_entries','v20_meetings','experiences','discipline_settings','discipline_scores','special_dates'] loop execute format('create policy "%s_owner" on public.%I for all to authenticated using (user_id=(select auth.uid())) with check (user_id=(select auth.uid()))',t,t); end loop; end $$;
create policy "family_profiles_member_read" on public.family_profiles for select to authenticated using(exists(select 1 from public.workspace_members m where m.workspace_id=family_profiles.workspace_id and m.user_id=(select auth.uid())));create policy "family_profiles_write" on public.family_profiles for insert to authenticated with check(exists(select 1 from public.workspace_members m where m.workspace_id=family_profiles.workspace_id and m.user_id=(select auth.uid()) and m.role in ('owner','admin','member')));
